17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        if (owner.getRegistrationDate() == null) {
111	            owner.setRegistrationDate(LocalDate.now());
112	        }
113	        this.clinicService.saveOwner(owner);
114	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
115	        headers.setLocation(UriComponentsBuilder.newInstance()
116	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
117	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
118	    }
119	
120	    /**
121	     * Determines whether an owner already exists that uses the same telephone number
122	     * as the given one. Telephone numbers must be unique across all owners. The
123	     * comparison ignores letter case and any surrounding or repeated whitespace.
124	     */
125	    private boolean isDuplicateOwner(Owner owner) {
126	        String telephone = normalize(owner.getTelephone());
127	        return this.clinicService.findAllOwners().stream()
128	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
129	    }
130	
131	    /**
132	     * Determines whether another owner already uses the same email address as the given one.
133	     * Email addresses, when supplied, must be unique across all owners. An owner without an
134	     * email address is never considered a duplicate. The comparison ignores letter case and
135	     * any surrounding or repeated whitespace.
136	     */
137	    private boolean isDuplicateEmail(Owner owner) {
138	        String email = normalize(owner.getEmail());
139	        if (email == null || email.isEmpty()) {
140	            return false;
141	        }
142	        return this.clinicService.findAllOwners().stream()
143	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
144	    }
145	
146	    /**
147	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
148	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
149	     * and "John Smith" normalize to the same key and so count as the same person.
150	     */
151	    private static String normalize(String value) {
152	        if (value == null) {
153	            return null;
154	        }
155	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
161	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
162	        if (currentOwner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        currentOwner.setAddress(ownerFieldsDto.getAddress());
166	        currentOwner.setCity(ownerFieldsDto.getCity());
167	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
168	        currentOwner.setLastName(ownerFieldsDto.getLastName());
169	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
170	        this.clinicService.saveOwner(currentOwner);
171	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Transactional
176	    @Override
177	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
178	        Owner owner = this.clinicService.findOwnerById(ownerId);
179	        if (owner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        this.clinicService.deleteOwner(owner);
183	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
189	        Owner owner = this.clinicService.findOwnerById(ownerId);
190	        if (owner == null) {
191	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	        }
193	        HttpHeaders headers = new HttpHeaders();
194	        Pet pet = petMapper.toPet(petFieldsDto);
195	        owner.setId(ownerId);
196	        pet.setOwner(owner);
197	        pet.getType().setName(null);
198	        this.clinicService.savePet(pet);
199	        PetDto petDto = petMapper.toPetDto(pet);
200	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
201	            .buildAndExpand(pet.getId()).toUri());
202	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
208	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
209	        if (currentOwner != null) {
210	            Pet currentPet = this.clinicService.findPetById(petId);
211	            if (currentPet != null) {
212	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
213	                currentPet.setName(petFieldsDto.getName());
214	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
215	                this.clinicService.savePet(currentPet);
216	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
217	            }
218	        }
219	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	    }
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
225	        HttpHeaders headers = new HttpHeaders();
226	        Visit visit = visitMapper.toVisit(visitFieldsDto);
227	        Pet pet = new Pet();
228	        pet.setId(petId);
229	        visit.setPet(pet);
230	        this.clinicService.saveVisit(visit);
231	        VisitDto visitDto = visitMapper.toVisitDto(visit);
232	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
233	            .buildAndExpand(visit.getId()).toUri());
234	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
235	    }
236	
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
241	        Owner owner = this.clinicService.findOwnerById(ownerId);
242	        if (owner != null) {
243	            Pet pet = owner.getPet(petId);
